INSERT INTO `ULhz1h_cmplz_cookiebanners` ( `ID`, `title`, `banner_version`, `default`, `position`, `checkbox_style`, `use_logo`, `logo_attachment_id`, `close_button`, `revoke`, `manage_consent_options`, `header`, `dismiss`, `save_preferences`, `view_preferences`, `category_functional`, `category_all`, `category_stats`, `category_prefs`, `accept`, `message_optin`, `use_categories`, `disable_cookiebanner`, `banner_width`, `soft_cookiewall`, `dismiss_on_scroll`, `dismiss_on_timeout`, `dismiss_timeout`, `accept_informational`, `message_optout`, `use_custom_cookie_css`, `custom_css`, `statistics`, `functional_text`, `statistics_text`, `statistics_text_anonymous`, `preferences_text`, `marketing_text`, `colorpalette_background`, `colorpalette_text`, `colorpalette_toggles`, `colorpalette_border_radius`, `border_width`, `font_size`, `colorpalette_button_accept`, `colorpalette_button_deny`, `colorpalette_button_settings`, `buttons_border_radius`, `animation`, `use_box_shadow`, `header_footer_shadow`, `hide_preview`, `disable_width_correction`, `legal_documents`) VALUES
(1, 'Banner A', 58, 1, 'bottom-right', 'slider', 'site', '0', '1', 'We value your privacy', 'hover-hide-mobile', 'a:2:{s:4:"text";s:21:"We value your privacy";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:4:"Deny";s:4:"show";i:1;}', 'Save preferences', 'View preferences', 'Functional', 'a:2:{s:4:"text";s:9:"Marketing";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:10:"Statistics";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:11:"Preferences";s:4:"show";i:1;}', 'Accept', 'To provide the best experiences, we use technologies like cookies to store and/or access device information. Consenting to these technologies will allow us to process data such as browsing behavior or unique IDs on this site. Not consenting or withdrawing consent, may adversely affect certain features and functions.', 'view-preferences', 0, 526, 0, 0, 0, '10', 'a:2:{s:4:"text";s:6:"Accept";s:4:"show";i:1;}', '<p>To provide the best experiences, we use technologies like cookies to store and/or access device information. By clicking "Accept", you consent to our use of cookies.</p>', '1', '/* Container */\n.cmplz-cookiebanner{}\n\n/* Logo */\n.cmplz-cookiebanner .cmplz-logo{}\n/* Title */\n.cmplz-cookiebanner .cmplz-title{}\n/* Close icon */\n.cmplz-cookiebanner .cmplz-close{}\n\n/* Message */\n.cmplz-cookiebanner .cmplz-message p {\n  font-size: 12px !important;\n}\n\n /* All buttons */\n.cmplz-buttons .cmplz-btn{}\n/* Accept button */\n.cmplz-btn .cmplz-accept{} \n /* Deny button */\n.cmplz-btn .cmplz-deny{}\n /* Save preferences button */\n.cmplz-btn .cmplz-deny{}\n /* View preferences button */\n.cmplz-btn .cmplz-deny{}\n\n /* Document hyperlinks */\n.cmplz-links .cmplz-documents a {\n  font-size: 12px !important;\n}\n\n /* Categories */\n.cmplz-cookiebanner .cmplz-category{}\n.cmplz-cookiebanner .cmplz-category-title{} \n\n/* Manage consent tab */\n#cmplz-manage-consent .cmplz-manage-consent{} \n\n/* Soft cookie wall */\n.cmplz-soft-cookiewall{}\n\n/* Placeholder button - Per category */\n.cmplz-blocked-content-container .cmplz-blocked-content-notice{}\n\n/* Placeholder button & message - Per service */\n.cmplz-blocked-content-container .cmplz-blocked-content-notice,\n.cmplz-blocked-content-notice{}\nbutton.cmplz-accept-service{}\n\n/* Styles for the AMP notice */\n#cmplz-consent-ui, #cmplz-post-consent-ui {}\n/* Message */\n#cmplz-consent-ui .cmplz-consent-message{}\n/* Buttons */\n#cmplz-consent-ui button, #cmplz-post-consent-ui button {}', 'a:0:{}', 'a:2:{s:4:"text";s:289:"The technical storage or access is strictly necessary for the legitimate purpose of enabling the use of a specific service explicitly requested by the subscriber or user, or for the sole purpose of carrying out the transmission of a communication over an electronic communications network.";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:82:"The technical storage or access that is used exclusively for statistical purposes.";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:317:"The technical storage or access that is used exclusively for anonymous statistical purposes. Without a subpoena, voluntary compliance on the part of your Internet Service Provider, or additional records from a third party, information stored or retrieved for this purpose alone cannot usually be used to identify you.";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:144:"The technical storage or access is necessary for the legitimate purpose of storing preferences that are not requested by the subscriber or user.";s:4:"show";i:1;}', 'a:2:{s:4:"text";s:181:"The technical storage or access is required to create user profiles to send advertising, or to track the user on a website or across several websites for similar marketing purposes.";s:4:"show";i:1;}', 'a:2:{s:5:"color";s:7:"#ffffff";s:6:"border";s:7:"#f2f2f2";}', 'a:2:{s:5:"color";s:7:"#222222";s:9:"hyperlink";s:7:"#1E73BE";}', 'a:3:{s:10:"background";s:7:"#1e73be";s:6:"bullet";s:7:"#ffffff";s:8:"inactive";s:7:"#F56E28";}', 'a:5:{s:3:"top";i:12;s:5:"right";i:12;s:6:"bottom";i:12;s:4:"left";i:12;s:4:"type";s:2:"px";}', 'a:4:{s:3:"top";i:0;s:5:"right";i:0;s:6:"bottom";i:0;s:4:"left";i:0;}', '14', 'a:3:{s:10:"background";s:7:"#090540";s:6:"border";s:7:"#090540";s:4:"text";s:7:"#ffffff";}', 'a:3:{s:10:"background";s:7:"#f9f9f9";s:6:"border";s:7:"#f2f2f2";s:4:"text";s:7:"#222222";}', 'a:3:{s:10:"background";s:7:"#f9f9f9";s:6:"border";s:7:"#f2f2f2";s:4:"text";s:7:"#333333";}', 'a:5:{s:3:"top";i:6;s:5:"right";i:6;s:6:"bottom";i:6;s:4:"left";i:6;s:4:"type";s:2:"px";}', 'fade', 1, 0, 0, 0, 1) ;
