(12910, 'wpesm_settings', 'a:18:{s:3:"key";s:0:"";s:15:"key_regenerated";i:1739227049;s:25:"key_regeneration_interval";i:604800;s:16:"allow_connection";b:0;s:10:"allow_pull";b:0;s:10:"allow_push";b:0;s:8:"profiles";a:0:{}s:7:"licence";s:0:"";s:10:"verify_ssl";b:0;s:17:"whitelist_plugins";a:0:{}s:11:"max_request";i:1048576;s:22:"delay_between_requests";i:0;s:18:"prog_tables_hidden";b:1;s:21:"pause_before_finalize";b:0;s:14:"allow_tracking";b:1;s:26:"high_performance_transfers";b:0;s:16:"settings_created";i:1739227049;s:18:"compatibility_mode";b:0;}', 'off'),
