(15664, 'cmplz_transients', 'a:30:{s:35:"cmplz_shortcode_cookie-statement-eu";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-eu";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:35:"cmplz_shortcode_cookie-statement-uk";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-uk";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:35:"cmplz_shortcode_cookie-statement-ca";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-ca";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:35:"cmplz_shortcode_cookie-statement-au";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-au";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:35:"cmplz_shortcode_cookie-statement-za";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-za";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:35:"cmplz_shortcode_cookie-statement-br";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_privacy-statement-br";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:29:"cmplz_shortcode_impressum-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1746117407;}s:36:"cmplz_shortcode_cookie-statement-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:37:"cmplz_shortcode_privacy-statement-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:46:"cmplz_shortcode_privacy-statement-children-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:28:"cmplz_shortcode_impressum-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:30:"cmplz_shortcode_disclaimer-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:29:"cmplz_shortcode_disclaimer-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739462171;}s:24:"cmplz_shortcode_12139-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739463347;}s:25:"cmplz_shortcode_12139-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739463347;}s:19:"cmplz_shortcode_-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739463347;}s:20:"cmplz_shortcode_-all";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1739463347;}s:45:"cmplz_shortcode_privacy-statement-children-us";a:2:{s:5:"value";s:4:"none";s:7:"expires";i:1774504510;}s:35:"cmplz_shortcode_cookie-statement-us";a:2:{s:5:"value";s:5:"12139";s:7:"expires";i:1774554845;}s:21:"cmplz_blocked_scripts";a:2:{s:5:"value";a:2:{s:21:"google.maps.MapTypeId";a:9:{s:4:"name";s:15:"acf-custom-maps";s:18:"enable_placeholder";s:1:"1";s:11:"placeholder";s:11:"google-maps";s:8:"category";s:9:"marketing";s:4:"urls";a:2:{i:0;s:21:"google.maps.MapTypeId";i:1;s:31:"maps.googleapis.com/maps/api/js";}s:6:"enable";i:1;s:17:"enable_dependency";s:1:"1";s:10:"dependency";a:1:{s:31:"maps.googleapis.com/maps/api/js";s:21:"google.maps.MapTypeId";}s:17:"placeholder_class";s:7:"acf-map";}s:31:"maps.googleapis.com/maps/api/js";a:9:{s:4:"name";s:15:"acf-custom-maps";s:18:"enable_placeholder";s:1:"1";s:11:"placeholder";s:11:"google-maps";s:8:"category";s:9:"marketing";s:4:"urls";a:2:{i:0;s:21:"google.maps.MapTypeId";i:1;s:31:"maps.googleapis.com/maps/api/js";}s:6:"enable";i:1;s:17:"enable_dependency";s:1:"1";s:10:"dependency";a:1:{s:31:"maps.googleapis.com/maps/api/js";s:21:"google.maps.MapTypeId";}s:17:"placeholder_class";s:7:"acf-map";}}s:7:"expires";i:1774555504;}s:23:"cmplz_default_banner_id";a:2:{s:5:"value";s:1:"1";s:7:"expires";i:1774557744;}s:19:"cmplz_min_banner_id";a:2:{s:5:"value";s:1:"1";s:7:"expires";i:1774557744;}s:18:"page_links_1_en_US";a:2:{s:5:"value";a:1:{s:2:"us";a:2:{s:16:"cookie-statement";a:2:{s:5:"title";s:19:"Opt-out preferences";s:3:"url";s:42:"https://worksandy.com/opt-out-preferences/";}s:17:"privacy-statement";a:2:{s:5:"title";s:14:"Privacy Policy";s:3:"url";s:37:"https://worksandy.