(5388, 269, '_flexible_content_blocks_4_slides_0_slide_content', 'field_663a298aa32b4'),
(5389, 269, 'flexible_content_blocks_4_slides_1_slide_content', 'Because we alleviate operational risks and headaches, allowing you to flex and grow without stress.'),
