(9429, 336, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(9430, 336, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(9431, 336, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(9432, 336, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(9433, 336, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
