(9438, 336, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(9439, 336, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(9440, 336, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(9441, 336, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
