(9445, 336, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(9446, 336, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(9447, 336, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(9448, 336, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
