INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(9465, 336, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(9466, 336, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(9467, 336, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
