(9471, 336, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(9472, 336, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(9473, 336, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(9474, 336, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(9475, 336, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
