(9479, 336, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(9480, 336, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(9481, 336, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(9482, 336, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
