INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(9893, 345, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(9894, 345, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(9895, 345, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(9896, 345, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(9897, 345, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(9898, 345, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(9899, 345, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(9900, 345, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(9901, 345, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(9902, 345, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(9903, 345, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
(9904, 345, '_flexible_content_blocks_2_slides_1_slide_icon', 'field_6644d1f02c90b'),
(9905, 345, 'flexible_content_blocks_2_slides_1_slide_eyebrow', ''),
(9906, 345, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(9907, 345, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(9908, 345, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(9909, 345, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(9910, 345, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(9911, 345, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(9912, 345, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(9913, 345, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(9914, 345, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(9915, 345, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(9916, 345, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(9917, 345, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(9918, 345, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(9919, 345, 'flexible_content_blocks_2_slides', '7'),
(9920, 345, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(9921, 345, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(9922, 345, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(9923, 345, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(9924, 345, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(9925, 345, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(9926, 345, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(9927, 345, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(9928, 345, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(9929, 345, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(9930, 345, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(9931, 345, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(9932, 345, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(9933, 345, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(9934, 345, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(9935, 345, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(9936, 345, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(9937, 345, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(9938, 345, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(9939, 345, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(9940, 345, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(9941, 345, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(9942, 345, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(9943, 345, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(9944, 345, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(9945, 345, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(9946, 345, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(9947, 345, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(9948, 345, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(9949, 345, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(9950, 345, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(9951, 345, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(9952, 345, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(9953, 345, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
(9954, 345, '_flexible_content_blocks_3_background_color_toggle', 'field_6648ff9e0bdfc'),
(9955, 345, 'flexible_content_blocks_3_background_image', ''),
(9956, 345, '_flexible_content_blocks_3_background_image', 'field_663a28f3a32ab'),
(9957, 345, 'flexible_content_blocks_3_block_eyebrow', ''),
(9958, 345, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(9959, 345, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(9960, 345, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(9961, 345, 'flexible_content_blocks_3_block_content', '<a class="button tertiary" href="#">Let\'s get started</a>'),
(9962, 345, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(9963, 345, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan Your Project</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(9964, 345, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(9965, 345, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build + Go</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(9966, 345, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
