(10130, 346, '_flexible_content_blocks_2_block_eyebrow', 'field_663a29d127350'),
(10131, 346, 'flexible_content_blocks_2_block_heading', 'We’re all about solving problems.'),
(10132, 346, '_flexible_content_blocks_2_block_heading', 'field_663a29d127351'),
(10133, 346, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(10134, 346, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(10135, 346, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(10136, 346, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(10137, 346, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(10138, 346, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(10139, 346, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(10140, 346, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(10141, 346, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(10142, 346, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(10143, 346, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
(10144, 346, '_flexible_content_blocks_2_slides_1_slide_icon', 'field_6644d1f02c90b'),
(10145, 346, 'flexible_content_blocks_2_slides_1_slide_eyebrow', ''),
(10146, 346, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(10147, 346, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(10148, 346, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(10149, 346, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(10150, 346, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(10151, 346, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(10152, 346, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(10153, 346, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(10154, 346, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(10155, 346, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(10156, 346, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(10157, 346, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(10158, 346, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(10159, 346, 'flexible_content_blocks_2_slides', '7'),
(10160, 346, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(10161, 346, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(10162, 346, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(10163, 346, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(10164, 346, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(10165, 346, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(10166, 346, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(10167, 346, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(10168, 346, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(10169, 346, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(10170, 346, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(10171, 346, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(10172, 346, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(10173, 346, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(10174, 346, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(10175, 346, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(10176, 346, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(10177, 346, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(10178, 346, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(10179, 346, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(10180, 346, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(10181, 346, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(10182, 346, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(10183, 346, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(10184, 346, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(10185, 346, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(10186, 346, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(10187, 346, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(10188, 346, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(10189, 346, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(10190, 346, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(10191, 346, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(10192, 346, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355') ;
