INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(13127, 11712, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(13128, 11712, 'flexible_content_blocks_1_block_heading', 'Get the right talent. <br>Drive more growth.'),
(13129, 11712, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(13130, 11712, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
(13131, 11712, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
(13132, 11712, 'flexible_content_blocks_1_block_cta', 'a:3:{s:5:"title";s:10:"Learn more";s:3:"url";s:32:"http://work-sandy.local/contact/";s:6:"target";s:0:"";}'),
