(13831, 11719, '_flexible_content_blocks_1_image_2_animation_style', 'field_663a1f7e6d480'),
(13832, 11719, 'flexible_content_blocks_1_block_eyebrow', 'For Businesses'),
(13833, 11719, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(13834, 11719, 'flexible_content_blocks_1_block_heading', 'Get the right talent. <br>Drive more growth.'),
(13835, 11719, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(13836, 11719, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
(13837, 11719, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
