(14068, 11721, 'flexible_content_blocks_1_block_eyebrow', 'For Businesses'),
(14069, 11721, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(14070, 11721, 'flexible_content_blocks_1_block_heading', 'Get the right talent. <br>Drive more growth.'),
(14071, 11721, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(14072, 11721, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
(14073, 11721, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
