(14811, 11728, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(14812, 11728, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(14813, 11728, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(14814, 11728, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(14815, 11728, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(14816, 11728, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(14817, 11728, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(14818, 11728, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(14819, 11728, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(14820, 11728, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(14821, 11728, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(14822, 11728, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(14823, 11728, 'flexible_content_blocks_2_slides', '7'),
(14824, 11728, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
