INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(14837, 11728, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(14838, 11728, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(14839, 11728, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(14840, 11728, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(14841, 11728, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(14842, 11728, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(14843, 11728, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(14844, 11728, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(14845, 11728, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(14846, 11728, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(14847, 11728, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(14848, 11728, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(14849, 11728, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(14850, 11728, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(14851, 11728, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(14852, 11728, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(14853, 11728, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(14854, 11728, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(14855, 11728, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(14856, 11728, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(14857, 11728, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
