(15070, 11730, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(15071, 11730, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(15072, 11730, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(15073, 11730, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(15074, 11730, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(15075, 11730, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(15076, 11730, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(15077, 11730, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(15078, 11730, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(15079, 11730, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(15080, 11730, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(15081, 11730, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(15082, 11730, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(15083, 11730, 'flexible_content_blocks_2_slides', '7'),
(15084, 11730, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(15085, 11730, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(15086, 11730, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(15087, 11730, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(15088, 11730, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(15089, 11730, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(15090, 11730, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(15091, 11730, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(15092, 11730, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(15093, 11730, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(15094, 11730, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(15095, 11730, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(15096, 11730, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(15097, 11730, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(15098, 11730, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(15099, 11730, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(15100, 11730, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(15101, 11730, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(15102, 11730, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(15103, 11730, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(15104, 11730, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(15105, 11730, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(15106, 11730, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(15107, 11730, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(15108, 11730, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(15109, 11730, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(15110, 11730, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(15111, 11730, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(15112, 11730, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(15113, 11730, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(15114, 11730, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(15115, 11730, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(15116, 11730, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(15117, 11730, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
