(15122, 11730, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(15123, 11730, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(15124, 11730, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(15125, 11730, 'flexible_content_blocks_3_block_content', '<a class="button tertiary" href="#">Let\'s get started</a>'),
(15126, 11730, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(15127, 11730, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan Your Project</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(15128, 11730, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(15129, 11730, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build + Go</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(15130, 11730, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
