(15501, 11733, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(15502, 11733, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(15503, 11733, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(15504, 11733, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(15505, 11733, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(15506, 11733, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(15507, 11733, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(15508, 11733, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(15509, 11733, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(15510, 11733, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(15511, 11733, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(15512, 11733, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(15513, 11733, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(15514, 11733, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(15515, 11733, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(15516, 11733, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(15517, 11733, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(15518, 11733, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(15519, 11733, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(15520, 11733, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(15521, 11733, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(15522, 11733, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(15523, 11733, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(15524, 11733, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(15525, 11733, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(15526, 11733, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(15527, 11733, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(15528, 11733, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(15529, 11733, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(15530, 11733, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(15531, 11733, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
(15532, 11733, '_flexible_content_blocks_3_background_color_toggle', 'field_6648ff9e0bdfc'),
