INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(15537, 11733, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(15538, 11733, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(15539, 11733, 'flexible_content_blocks_3_block_content', '<a class="button tertiary" href="#">Let\'s get started</a>'),
(15540, 11733, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(15541, 11733, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan Your Project</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(15542, 11733, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(15543, 11733, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build + Go</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(15544, 11733, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
(15545, 11733, 'flexible_content_blocks_3_slides_2_slide_content', '<h3>Management  INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
