(15668, 11733, '_flexible_content_blocks_8_column_2_cta_class', 'field_663a24d04344e'),
(15669, 11733, 'flexible_content_blocks_1_block_image', '11727'),
(15670, 11733, '_flexible_content_blocks_1_block_image', 'field_664e546108379'),
(15671, 11733, 'flexible_content_blocks_3_text_color_toggle', 'primary'),
(15672, 11733, '_flexible_content_blocks_3_text_color_toggle', 'field_664b91edc94fe'),
(15673, 11733, 'flexible_content_blocks_3_slider_section_heading', ''),
(15674, 11733, '_flexible_content_blocks_3_slider_section_heading', 'field_664fec9759b9a'),
(15675, 11733, 'flexible_content_blocks_4_bricks_0_brick_details', 'You get access to our carefully vetted, world-class talent - most of which having 8+ years experience in their field. When we say we work with the best, we mean it.'),
(15676, 11733, '_flexible_content_blocks_4_bricks_0_brick_details', 'field_664fecc859b9b'),
(15677, 11733, 'flexible_content_blocks_4_bricks_1_brick_details', 'We handle all the heavy lifting—including recruiting, talent contracts, onboarding, payments and more.'),
(15678, 11733, '_flexible_content_blocks_4_bricks_1_brick_details', 'field_664fecc859b9b'),
(15679, 11733, 'flexible_content_blocks_4_bricks_2_brick_details', 'We excel in building teams for different needs and sizes. We’re seasoned marketers that know what it takes to help achieve your goals and meet your needs.'),
(15680, 11733, '_flexible_content_blocks_4_bricks_2_brick_details', 'field_664fecc859b9b'),
(15681, 11733, 'flexible_content_blocks_4_bricks_3_brick_details', 'We’ve got flexible solutions for all your challenges—from juggling goals and budgets to handling your to-do lists. And we provide next-level support every step of the way.'),
(15682, 11733, '_flexible_content_blocks_4_bricks_3_brick_details', 'field_664fecc859b9b'),
(15683, 11733, 'flexible_content_blocks_4_bricks_4_brick_details', 'We go the extra mile for our talent, creating close-knit relationships. We know them well, we collaborate with them, and we offer a range of benefits to fit their needs.'),
(15684, 11733, '_flexible_content_blocks_4_bricks_4_brick_details', 'field_664fecc859b9b'),
(15685, 11734, '_wp_attached_file', '2024/05/Mission.svg'),
