(15710, 11735, '_flexible_content_blocks_1_block_eyebrow', 'field_663a26d5473fb'),
(15711, 11735, 'flexible_content_blocks_1_block_heading', 'Here at Sandy, we aim to simplify the complexities of finding and managing talent, helping you build, grow, and scale with ease.'),
