(15723, 11735, 'flexible_content_blocks_2_block_eyebrow', ''),
(15724, 11735, '_flexible_content_blocks_2_block_eyebrow', 'field_5c1ac7d89a382'),
(15725, 11735, 'flexible_content_blocks_2_block_heading', 'Our Mission'),
(15726, 11735, '_flexible_content_blocks_2_block_heading', 'field_5c1ac7ff9a383'),
(15727, 11735, 'flexible_content_blocks_2_block_content', 'We work closely with companies and organizations to help unlock their full potential through improved alignment, performance, and culture.\r\n\r\nWhen you partner with us, you get a crew of experts who excel at team building and talent solutions.'),
(15728, 11735, '_flexible_content_blocks_2_block_content', 'field_5c1ac8069a384'),
(15729, 11735, 'flexible_content_blocks_2_block_cta', 'a:3:{s:5:"title";s:11:"Get Started";s:3:"url";s:32:"http://work-sandy.local/contact/";s:6:"target";s:0:"";}'),
