(15793, 11735, 'flexible_content_blocks_5_slides_1_slide_content', 'We take a back-to-basics approach with simplified hiring, transparent pricing, and cutting through the chaos of team management.'),
(15794, 11735, '_flexible_content_blocks_5_slides_1_slide_content', 'field_663a29d127355'),
