(16888, 11741, '_flexible_content_blocks_4_block_eyebrow', 'field_663a2947a32af'),
(16889, 11741, 'flexible_content_blocks_4_block_heading', 'Why Sandy'),
(16890, 11741, '_flexible_content_blocks_4_block_heading', 'field_663a294fa32b0'),
(16891, 11741, 'flexible_content_blocks_4_block_content', 'We’re a team of agency vets and marketing specialists who help you create smarter, flexible, and more intelligent solutions. We work tirelessly to solve the challenges of finding and managing creative talent, giving you trusted resourcing solutions tailored to your needs. Here’s a closer look at why our partners work with us…'),
(16892, 11741, '_flexible_content_blocks_4_block_content', 'field_663a295ca32b1') ;
