(17649, 11766, '_flexible_content_blocks_2_block_eyebrow', 'field_663a29d127350'),
(17650, 11766, 'flexible_content_blocks_2_block_heading', 'We’re all about solving problems.'),
(17651, 11766, '_flexible_content_blocks_2_block_heading', 'field_663a29d127351'),
(17652, 11766, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(17653, 11766, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(17654, 11766, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(17655, 11766, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(17656, 11766, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(17657, 11766, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(17658, 11766, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(17659, 11766, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(17660, 11766, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(17661, 11766, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(17662, 11766, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
