(17665, 11766, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(17666, 11766, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(17667, 11766, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(17668, 11766, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(17669, 11766, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(17670, 11766, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(17671, 11766, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(17672, 11766, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(17673, 11766, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(17674, 11766, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(17675, 11766, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(17676, 11766, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(17677, 11766, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(17678, 11766, 'flexible_content_blocks_2_slides', '7'),
(17679, 11766, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(17680, 11766, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
