(17683, 11766, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(17684, 11766, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(17685, 11766, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(17686, 11766, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(17687, 11766, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(17688, 11766, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(17689, 11766, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(17690, 11766, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(17691, 11766, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(17692, 11766, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(17693, 11766, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(17694, 11766, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(17695, 11766, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(17696, 11766, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
