INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(17700, 11766, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(17701, 11766, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(17702, 11766, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(17703, 11766, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(17704, 11766, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(17705, 11766, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(17706, 11766, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(17707, 11766, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(17708, 11766, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(17709, 11766, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(17710, 11766, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(17711, 11766, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(17712, 11766, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
