(17717, 11766, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(17718, 11766, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(17719, 11766, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(17720, 11766, 'flexible_content_blocks_3_block_content', '<a class="button tertiary" href="#">Let\'s get started</a>'),
(17721, 11766, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(17722, 11766, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan Your Project</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(17723, 11766, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
