(17900, 11767, 'flexible_content_blocks_2_block_eyebrow', ''),
(17901, 11767, '_flexible_content_blocks_2_block_eyebrow', 'field_663a29d127350'),
(17902, 11767, 'flexible_content_blocks_2_block_heading', 'We’re all about solving problems.'),
(17903, 11767, '_flexible_content_blocks_2_block_heading', 'field_663a29d127351'),
(17904, 11767, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(17905, 11767, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(17906, 11767, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(17907, 11767, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(17908, 11767, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(17909, 11767, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(17910, 11767, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(17911, 11767, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(17912, 11767, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(17913, 11767, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(17914, 11767, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
