(17918, 11767, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(17919, 11767, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(17920, 11767, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(17921, 11767, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(17922, 11767, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(17923, 11767, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(17924, 11767, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(17925, 11767, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(17926, 11767, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(17927, 11767, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(17928, 11767, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(17929, 11767, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(17930, 11767, 'flexible_content_blocks_2_slides', '7'),
(17931, 11767, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
