(17936, 11767, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(17937, 11767, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(17938, 11767, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(17939, 11767, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(17940, 11767, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
