(17944, 11767, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(17945, 11767, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(17946, 11767, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(17947, 11767, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(17948, 11767, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(17949, 11767, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(17950, 11767, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(17951, 11767, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(17952, 11767, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(17953, 11767, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(17954, 11767, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(17955, 11767, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(17956, 11767, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(17957, 11767, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(17958, 11767, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(17959, 11767, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(17960, 11767, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(17961, 11767, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(17962, 11767, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(17963, 11767, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(17964, 11767, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
