(17971, 11767, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(17972, 11767, 'flexible_content_blocks_3_block_content', '<a class="button tertiary" href="#">Let\'s get started</a>'),
(17973, 11767, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(17974, 11767, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan Your Project</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(17975, 11767, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(17976, 11767, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build + Go</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
