(18162, 11768, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(18163, 11768, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(18164, 11768, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(18165, 11768, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(18166, 11768, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
