(18170, 11768, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(18171, 11768, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(18172, 11768, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(18173, 11768, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(18174, 11768, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(18175, 11768, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(18176, 11768, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(18177, 11768, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(18178, 11768, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(18179, 11768, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(18180, 11768, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(18181, 11768, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(18182, 11768, 'flexible_content_blocks_2_slides', '7'),
(18183, 11768, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(18184, 11768, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(18185, 11768, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(18186, 11768, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(18187, 11768, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(18188, 11768, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(18189, 11768, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(18190, 11768, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(18191, 11768, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(18192, 11768, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(18193, 11768, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(18194, 11768, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(18195, 11768, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(18196, 11768, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(18197, 11768, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(18198, 11768, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(18199, 11768, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355') ;
