(18204, 11768, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(18205, 11768, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(18206, 11768, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(18207, 11768, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(18208, 11768, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
