(18211, 11768, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(18212, 11768, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(18213, 11768, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(18214, 11768, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(18215, 11768, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
