(18405, 11769, '_flexible_content_blocks_2_block_eyebrow', 'field_663a29d127350'),
(18406, 11769, 'flexible_content_blocks_2_block_heading', 'We’re all about solving problems.'),
(18407, 11769, '_flexible_content_blocks_2_block_heading', 'field_663a29d127351'),
(18408, 11769, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(18409, 11769, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(18410, 11769, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(18411, 11769, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(18412, 11769, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(18413, 11769, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(18414, 11769, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(18415, 11769, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(18416, 11769, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(18417, 11769, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(18418, 11769, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
