(18421, 11769, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(18422, 11769, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(18423, 11769, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(18424, 11769, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(18425, 11769, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(18426, 11769, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(18427, 11769, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(18428, 11769, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(18429, 11769, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(18430, 11769, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(18431, 11769, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(18432, 11769, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(18433, 11769, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(18434, 11769, 'flexible_content_blocks_2_slides', '7'),
(18435, 11769, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(18436, 11769, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(18437, 11769, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(18438, 11769, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(18439, 11769, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(18440, 11769, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(18441, 11769, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(18442, 11769, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(18443, 11769, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(18444, 11769, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(18445, 11769, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(18446, 11769, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(18447, 11769, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(18448, 11769, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(18449, 11769, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(18450, 11769, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(18451, 11769, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(18452, 11769, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(18453, 11769, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(18454, 11769, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(18455, 11769, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(18456, 11769, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(18457, 11769, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(18458, 11769, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(18459, 11769, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(18460, 11769, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(18461, 11769, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(18462, 11769, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(18463, 11769, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(18464, 11769, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(18465, 11769, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(18466, 11769, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(18467, 11769, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(18468, 11769, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
(18469, 11769, '_flexible_content_blocks_3_background_color_toggle', 'field_6648ff9e0bdfc'),
