(18471, 11769, '_flexible_content_blocks_3_background_image', 'field_663a28f3a32ab'),
(18472, 11769, 'flexible_content_blocks_3_block_eyebrow', ''),
(18473, 11769, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(18474, 11769, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(18475, 11769, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(18476, 11769, 'flexible_content_blocks_3_block_content', '<a class="button secondary-solid" href="#">Let\'s get started</a>'),
(18477, 11769, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(18478, 11769, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team - all built around your budget and timing. And hey, we know plans change, so we’ll be your partner for the long-haul.'),
(18479, 11769, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(18480, 11769, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(18481, 11769, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
(18482, 11769, 'flexible_content_blocks_3_slides_2_slide_content', '<h3>Manage</h3>\r\nOur first-class onboarding helps you hit the ground running. Once we start, we work closely with you to help you manage your team and achieve success.'),
(18483, 11769, '_flexible_content_blocks_3_slides_2_slide_content', 'field_663a298aa32b4'),
(18484, 11769, 'flexible_content_blocks_3_slides', '3'),
