(18643, 11770, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(18644, 11770, 'flexible_content_blocks_1_block_heading', 'For us, simplicity is paramount for your growth and success. '),
(18645, 11770, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(18646, 11770, 'flexible_content_blocks_1_block_content', 'So we offer an Elastic Team solution that focuses on getting you the right people at the right time. Thanks to our streamlined approach and mega-talented network, you can worry less and focus more on your goals.'),
(18647, 11770, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
