(18702, 11770, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(18703, 11770, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(18704, 11770, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(18705, 11770, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(18706, 11770, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(18707, 11770, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(18708, 11770, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(18709, 11770, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(18710, 11770, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(18711, 11770, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(18712, 11770, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(18713, 11770, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(18714, 11770, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(18715, 11770, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(18716, 11770, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(18717, 11770, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(18718, 11770, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(18719, 11770, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(18720, 11770, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
