INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(18902, 11771, 'flexible_content_blocks_1_block_content', 'If you want flexible solutions with superstar creatives and marketing pros, you’re in the right place. When you partner with Sandy, you get a team of seasoned marketers to help achieve your objectives—which means less worry and more reaching your goals.'),
