INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(19504, 11799, '_flexible_content_blocks_1_layout_toggle', 'field_5c1ac6ec9a37e'),
(19505, 11799, 'flexible_content_blocks_1_block_animation_style', ''),
(19506, 11799, '_flexible_content_blocks_1_block_animation_style', 'field_663a1f7e6d480'),
(19507, 11799, 'flexible_content_blocks_1_block_eyebrow', ''),
(19508, 11799, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(19509, 11799, 'flexible_content_blocks_1_block_heading', 'For us, simplicity is paramount for your growth and success. '),
(19510, 11799, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(19511, 11799, 'flexible_content_blocks_1_block_content', 'So we offer an Elastic Team solution that focuses on getting you the right people at the right time. Thanks to our streamlined approach and mega-talented network, you can worry less and focus more on your goals.'),
(19512, 11799, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
(19513, 11799, 'flexible_content_blocks_1_block_cta', 'a:3:{s:5:"title";s:11:"Get started";s:3:"url";s:32:"http://work-sandy.local/contact/";s:6:"target";s:0:"";}'),
(19514, 11799, '_flexible_content_blocks_1_block_cta', 'field_663a20a703b5f'),
(19515, 11799, 'flexible_content_blocks_1_block_cta_class', 'primary-solid'),
(19516, 11799, '_flexible_content_blocks_1_block_cta_class', 'field_663a252d43451'),
(19517, 11799, 'flexible_content_blocks_2_background_image', '11729'),
(19518, 11799, '_flexible_content_blocks_2_background_image', 'field_663a29d12734c'),
(19519, 11799, 'flexible_content_blocks_2_bg_image_animation_style', 'fade-in'),
(19520, 11799, '_flexible_content_blocks_2_bg_image_animation_style', 'field_663a29d12734d'),
(19521, 11799, 'flexible_content_blocks_2_block_eyebrow', ''),
(19522, 11799, '_flexible_content_blocks_2_block_eyebrow', 'field_663a29d127350'),
(19523, 11799, 'flexible_content_blocks_2_block_heading', 'We’re all about solving problems.'),
(19524, 11799, '_flexible_content_blocks_2_block_heading', 'field_663a29d127351'),
(19525, 11799, 'flexible_content_blocks_2_block_content', 'We like to make things easy and stress-free - every step of the way. If you’re running into these issues, we’re here to help.'),
(19526, 11799, '_flexible_content_blocks_2_block_content', 'field_663a29d127352'),
(19527, 11799, 'flexible_content_blocks_2_slides_0_slide_icon', '295'),
(19528, 11799, '_flexible_content_blocks_2_slides_0_slide_icon', 'field_6644d1f02c90b'),
(19529, 11799, 'flexible_content_blocks_2_slides_0_slide_eyebrow', ''),
(19530, 11799, '_flexible_content_blocks_2_slides_0_slide_eyebrow', 'field_663a29f727356'),
(19531, 11799, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(19532, 11799, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(19533, 11799, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(19534, 11799, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(19535, 11799, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
(19536, 11799, '_flexible_content_blocks_2_slides_1_slide_icon', 'field_6644d1f02c90b'),
(19537, 11799, 'flexible_content_blocks_2_slides_1_slide_eyebrow', ''),
(19538, 11799, '_flexible_content_blocks_2_slides_1_slide_eyebrow', 'field_663a29f727356'),
(19539, 11799, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(19540, 11799, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(19541, 11799, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(19542, 11799, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(19543, 11799, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(19544, 11799, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(19545, 11799, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(19546, 11799, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(19547, 11799, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(19548, 11799, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(19549, 11799, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(19550, 11799, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(19551, 11799, 'flexible_content_blocks_2_slides', '7'),
(19552, 11799, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(19553, 11799, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
(19554, 11799, '_flexible_content_blocks_2_slides_3_slide_icon', 'field_6644d1f02c90b'),
(19555, 11799, 'flexible_content_blocks_2_slides_3_slide_eyebrow', ''),
(19556, 11799, '_flexible_content_blocks_2_slides_3_slide_eyebrow', 'field_663a29f727356'),
(19557, 11799, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(19558, 11799, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(19559, 11799, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(19560, 11799, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(19561, 11799, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
(19562, 11799, '_flexible_content_blocks_2_slides_4_slide_icon', 'field_6644d1f02c90b'),
(19563, 11799, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(19564, 11799, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(19565, 11799, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(19566, 11799, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(19567, 11799, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(19568, 11799, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(19569, 11799, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(19570, 11799, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(19571, 11799, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(19572, 11799, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(19573, 11799, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(19574, 11799, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(19575, 11799, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(19576, 11799, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(19577, 11799, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(19578, 11799, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(19579, 11799, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(19580, 11799, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(19581, 11799, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(19582, 11799, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(19583, 11799, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(19584, 11799, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(19585, 11799, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
(19586, 11799, '_flexible_content_blocks_3_background_color_toggle', 'field_6648ff9e0bdfc'),
(19587, 11799, 'flexible_content_blocks_3_background_image', ''),
(19588, 11799, '_flexible_content_blocks_3_background_image', 'field_663a28f3a32ab'),
(19589, 11799, 'flexible_content_blocks_3_block_eyebrow', ''),
(19590, 11799, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(19591, 11799, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(19592, 11799, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(19593, 11799, 'flexible_content_blocks_3_block_content', '<a class="button secondary-solid" href="#">Let\'s get started</a>'),
(19594, 11799, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(19595, 11799, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team, all built around your budget and timing. We also take into account that your team will grow and change as your needs evolve - and we’ll be your partner through it all.'),
(19596, 11799, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(19597, 11799, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(19598, 11799, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
(19599, 11799, 'flexible_content_blocks_3_slides_2_slide_content', '<h3>Manage</h3>\r\nOur first-class onboarding helps you hit the ground running. Once we start, we work closely with you to help you manage your team and achieve success.'),
(19600, 11799, '_flexible_content_blocks_3_slides_2_slide_content', 'field_663a298aa32b4'),
(19601, 11799, 'flexible_content_blocks_3_slides', '3'),
