(19750, 11800, '_flexible_content_blocks_0_hero_eyebrow', 'field_663a2c57af422'),
(19751, 11800, 'flexible_content_blocks_0_hero_heading', 'Creative resourcing. Simply done better.'),
(19752, 11800, '_flexible_content_blocks_0_hero_heading', 'field_663a1e395c04c'),
(19753, 11800, 'flexible_content_blocks_0_hero_content', 'At Sandy, we excel at helping you solve your creative resourcing challenges. We’re industry experts with agency chops and a robust, highly-talented network, making it easy for you and your teams to succeed at any level.'),
(19754, 11800, '_flexible_content_blocks_0_hero_content', 'field_663a1e485c04d'),
