(19778, 11800, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(19779, 11800, 'flexible_content_blocks_1_block_heading', 'Get the right talent. Drive more growth.'),
(19780, 11800, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(19781, 11800, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
