(20247, 11802, 'flexible_content_blocks_1_block_heading', 'Get the right talent. Drive more growth.'),
(20248, 11802, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(20249, 11802, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
(20250, 11802, '_flexible_content_blocks_1_block_content', 'field_5c1ac8069a384'),
