INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(22428, 11903, 'flexible_content_blocks_3_block_heading', 'Our Story'),
(22429, 11903, '_flexible_content_blocks_3_block_heading', 'field_5c1ac7ff9a383'),
(22430, 11903, 'flexible_content_blocks_3_block_content', 'Back in 2019, we saw a transformation in the modern workspace and came up with a crazy idea: let’s make it way easier for companies to drive growth and unleash innovation with an Elastic Team solution. Since then, we’ve built a diverse, ever-growing community of 5,000+ creatives - all vetted for experience, excellence, and being just plain awesome.\r\n\r\nThanks to our bespoke approach, we continue to build teams that are effective, accountable, and remarkably successful.'),
(22431, 11903, '_flexible_content_blocks_3_block_content', 'field_5c1ac8069a384'),
(22432, 11903, 'flexible_content_blocks_3_block_cta', ''),
