(22660, 11904, 'flexible_content_blocks_2_slides_0_slide_heading', 'Workload '),
(22661, 11904, '_flexible_content_blocks_2_slides_0_slide_heading', 'field_663a2a0327357'),
(22662, 11904, 'flexible_content_blocks_2_slides_0_slide_content', 'From the busy season blitz to creative burnout, we ensure you’ve got that little extra support to meet all the deliverables on time.'),
(22663, 11904, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a29d127355'),
(22664, 11904, 'flexible_content_blocks_2_slides_1_slide_icon', '296'),
