(22669, 11904, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(22670, 11904, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(22671, 11904, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(22672, 11904, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
