(22694, 11904, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(22695, 11904, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(22696, 11904, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(22697, 11904, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(22698, 11904, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
