(22702, 11904, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(22703, 11904, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(22704, 11904, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(22705, 11904, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(22706, 11904, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(22707, 11904, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(22708, 11904, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(22709, 11904, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(22710, 11904, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(22711, 11904, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(22712, 11904, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(22713, 11904, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(22714, 11904, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
