(22719, 11904, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(22720, 11904, 'flexible_content_blocks_3_block_heading', 'How it <br>Works'),
(22721, 11904, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(22722, 11904, 'flexible_content_blocks_3_block_content', '<a class="button secondary-solid" href="#">Let\'s get started</a>'),
(22723, 11904, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(22724, 11904, 'flexible_content_blocks_3_slides_0_slide_content', '<h3>Plan</h3>\r\nTell us your challenge and we\'ll devise a plan and assemble the perfect team, all built around your budget and timing. We also take into account that your team will grow and change as your needs evolve - and we’ll be your partner through it all.'),
(22725, 11904, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(22726, 11904, 'flexible_content_blocks_3_slides_1_slide_content', '<h3>Build</h3>\r\nWhether you’re growing your team or creating a new one, we ensure the talent aligns with your objectives and effectively helps achieve your goals.'),
(22727, 11904, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4') ;
