(22926, 11905, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(22927, 11905, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(22928, 11905, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(22929, 11905, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(22930, 11905, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
