(22934, 11905, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(22935, 11905, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(22936, 11905, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(22937, 11905, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
