(22952, 11905, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(22953, 11905, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(22954, 11905, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(22955, 11905, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(22956, 11905, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
