(22960, 11905, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(22961, 11905, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(22962, 11905, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(22963, 11905, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
