(23175, 11906, '_flexible_content_blocks_2_block_eyebrow', 'field_663a2947a32af'),
(23176, 11906, 'flexible_content_blocks_2_block_heading', 'Why work <br>with Sandy'),
(23177, 11906, '_flexible_content_blocks_2_block_heading', 'field_663a294fa32b0'),
(23178, 11906, 'flexible_content_blocks_2_block_content', ''),
(23179, 11906, '_flexible_content_blocks_2_block_content', 'field_663a295ca32b1'),
(23180, 11906, 'flexible_content_blocks_2_slides_0_slide_content', '<h3><b>Roles Fit For You</b></h3>\r\n<span style="font-weight: 400;">Our Elastic Teams offer a wide range of opportunities in our network. We work with you to find roles that align with your skills and expertise.</span>'),
(23181, 11906, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a298aa32b4'),
(23182, 11906, 'flexible_content_blocks_2_slides_1_slide_content', '<h3>Bye, Bye Paperwork</h3>\r\n<span style="font-weight: 400;">We handle your negotiation, contracts, invoicing, and payments, so you can focus on getting to work.</span>'),
(23183, 11906, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a298aa32b4'),
(23184, 11906, 'flexible_content_blocks_2_slides_2_slide_content', '<h3><b>Better Compensation and Benefits</b></h3>\r\n<span style="font-weight: 400;">It’s tough to get the pay and perks you want. Our team works tirelessly to get the most competitive rate in your field, plus a range of great benefits.</span>'),
(23185, 11906, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a298aa32b4'),
(23186, 11906, 'flexible_content_blocks_2_slides_3_slide_content', '<h3>Serious Support</h3>\r\n<span style="font-weight: 400;">We’re always in touch with you </span><i><span style="font-weight: 400;">and</span></i><span style="font-weight: 400;"> the client, ensuring you have the support you need to perform and succeed. We want to ensure it works great for all parties involved.</span>'),
(23187, 11906, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a298aa32b4'),
(23188, 11906, 'flexible_content_blocks_2_slides', '5'),
