(24109, 11924, '_flexible_content_blocks_0_hero_eyebrow', 'field_663a2c57af422'),
(24110, 11924, 'flexible_content_blocks_0_hero_heading', 'Creative resourcing. Simply done better.'),
(24111, 11924, '_flexible_content_blocks_0_hero_heading', 'field_663a1e395c04c'),
(24112, 11924, 'flexible_content_blocks_0_hero_content', 'At Sandy, we excel at helping you solve your creative resourcing challenges. We’re industry experts with agency chops and a robust, highly-talented network, making it easy for you and your teams to succeed at any level.'),
