(24136, 11924, 'flexible_content_blocks_1_block_eyebrow', 'For Businesses'),
(24137, 11924, '_flexible_content_blocks_1_block_eyebrow', 'field_5c1ac7d89a382'),
(24138, 11924, 'flexible_content_blocks_1_block_heading', 'Get the right talent. Drive more growth.'),
(24139, 11924, '_flexible_content_blocks_1_block_heading', 'field_5c1ac7ff9a383'),
(24140, 11924, 'flexible_content_blocks_1_block_content', 'We carefully curate our talent pool so you always get the perfect fit. With flexible, simple Elastic Team solutions, we eliminate the hassle of finding, hiring, and managing talent, so you can focus more on the important stuff: like driving growth and unleashing innovation.'),
