(24611, 11926, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(24612, 11926, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(24613, 11926, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(24614, 11926, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
