(24644, 11926, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(24645, 11926, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(24646, 11926, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(24647, 11926, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(24648, 11926, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(24649, 11926, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(24650, 11926, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(24651, 11926, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(24652, 11926, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(24653, 11926, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(24654, 11926, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(24655, 11926, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(24656, 11926, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
