(24868, 11927, 'flexible_content_blocks_2_slides_1_slide_heading', 'Skill Boost'),
(24869, 11927, '_flexible_content_blocks_2_slides_1_slide_heading', 'field_663a2a0327357'),
(24870, 11927, 'flexible_content_blocks_2_slides_1_slide_content', 'Need to fill a skills gap? Our network of creatives will help you bridge it with ease.'),
(24871, 11927, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
(24872, 11927, 'flexible_content_blocks_2_slides_2_slide_icon', '299'),
(24873, 11927, '_flexible_content_blocks_2_slides_2_slide_icon', 'field_6644d1f02c90b'),
(24874, 11927, 'flexible_content_blocks_2_slides_2_slide_eyebrow', ''),
(24875, 11927, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(24876, 11927, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(24877, 11927, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(24878, 11927, 'flexible_content_blocks_2_slides_2_slide_content', 'Whether you’re unsure where to invest in your headcount or just need to scale quickly, our industry experts will help you do it wisely and efficiently.'),
(24879, 11927, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(24880, 11927, 'flexible_content_blocks_2_slides', '7'),
(24881, 11927, '_flexible_content_blocks_2_slides', 'field_663a29d127353'),
(24882, 11927, 'flexible_content_blocks_2_slides_3_slide_icon', '300'),
