(24886, 11927, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(24887, 11927, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(24888, 11927, 'flexible_content_blocks_2_slides_3_slide_content', 'Need a quick replacement for maternity leave or an unexpected resignation? Our process is designed to minimize disruption.'),
(24889, 11927, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(24890, 11927, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
