INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(24892, 11927, 'flexible_content_blocks_2_slides_4_slide_eyebrow', ''),
(24893, 11927, '_flexible_content_blocks_2_slides_4_slide_eyebrow', 'field_663a29f727356'),
(24894, 11927, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(24895, 11927, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(24896, 11927, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing helps you stay on budget. With our Elastic Teams, you’ll save more time and money than traditional solutions (even with your in-house HR partners).'),
(24897, 11927, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(24898, 11927, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(24899, 11927, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(24900, 11927, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(24901, 11927, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(24902, 11927, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(24903, 11927, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(24904, 11927, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. So, let us manage it in exchange for one simple monthly invoice.'),
(24905, 11927, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(24906, 11927, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(24907, 11927, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(24908, 11927, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(24909, 11927, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(24910, 11927, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(24911, 11927, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(24912, 11927, 'flexible_content_blocks_2_slides_6_slide_content', 'We’re passionate about treating our teams the right way. Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. Plus they always have a connection at Sandy to support their questions and concerns.'),
(24913, 11927, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(24914, 11927, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
