(25125, 11928, '_flexible_content_blocks_1_hero_eyebrow', 'field_663a2c57af422'),
(25126, 11928, 'flexible_content_blocks_1_hero_heading', 'Become part of our growing community'),
(25127, 11928, '_flexible_content_blocks_1_hero_heading', 'field_663a1e395c04c'),
(25128, 11928, 'flexible_content_blocks_1_hero_content', 'Did you know that roughly half the workforce will be freelance by 2027? So what better reason to join our creative talent pool. When you’re part of Sandy, you’ll have access to a range of roles with some of the best agencies and brands in the game.'),
(25129, 11928, '_flexible_content_blocks_1_hero_content', 'field_663a1e485c04d'),
