(25220, 11928, 'flexible_content_blocks_4_testimonials_1_icon', '328'),
(25221, 11928, '_flexible_content_blocks_4_testimonials_1_icon', 'field_664a9305b2657'),
(25222, 11928, 'flexible_content_blocks_4_testimonials_1_testimonial', 'Very grateful for all of the kindness, guidance, and professionalism of everyone I’ve interacted with.'),
