(25249, 11928, '_flexible_content_blocks_2_slider_section_heading', 'field_664fec9759b9a'),
(25250, 11928, 'flexible_content_blocks_2_slides_4_slide_content', '<h3><strong>Total Flexibility</strong></h3>\r\n<span style="font-weight: 400;">We give you the freedom to choose the clients that best suit your needs. Plus, most of our clients offer remote work, so you don’t have to move for that dream gig.</span>'),
(25251, 11928, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a298aa32b4'),
(25252, 11928, 'flexible_content_blocks_4_testimonials_2_icon', '328'),
(25253, 11928, '_flexible_content_blocks_4_testimonials_2_icon', 'field_664a9305b2657'),
(25254, 11928, 'flexible_content_blocks_4_testimonials_2_testimonial', 'SANDY is phenomenal! You are nothing like others I have worked for. I always had a positive experience with the entire Sandy team.'),
(25255, 11928, '_flexible_content_blocks_4_testimonials_2_testimonial', 'field_664a88072f803'),
(25256, 11928, 'flexible_content_blocks_4_testimonials_2_attribution', 'James'),
(25257, 11928, '_flexible_content_blocks_4_testimonials_2_attribution', 'field_664a883f2f804'),
(25258, 11928, 'flexible_content_blocks_4_testimonials_3_icon', '328'),
(25259, 11928, '_flexible_content_blocks_4_testimonials_3_icon', 'field_664a9305b2657'),
(25260, 11928, 'flexible_content_blocks_4_testimonials_3_testimonial', 'I am thrilled to have been a part of what Sandy is providing for not only the  creative industry, but the freelance space. I haven’t met any person connected to Sandy that wasn’t an absolute gem of a being.'),
