(25539, 11999, '_flexible_content_blocks_2_block_heading', 'field_5c1ac7ff9a383'),
(25540, 11999, 'flexible_content_blocks_2_block_content', 'We work closely with companies and organizations to help unlock their full potential through improved alignment, performance, and culture.\r\n\r\nWhen you partner with us, you get a crew of experts who excel at team building and talent solutions.'),
