(26817, 12051, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(26818, 12051, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(26819, 12051, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing ensures you stay on budget, and our Elastic Teams help save more time and money than traditional solutions.'),
(26820, 12051, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(26821, 12051, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
