(26825, 12051, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(26826, 12051, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(26827, 12051, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(26828, 12051, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(26829, 12051, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
