(28190, 12104, '_flexible_content_blocks_3_block_eyebrow', 'field_663a2947a32af'),
(28191, 12104, 'flexible_content_blocks_3_block_heading', 'Why Sandy'),
(28192, 12104, '_flexible_content_blocks_3_block_heading', 'field_663a294fa32b0'),
(28193, 12104, 'flexible_content_blocks_3_block_content', '<span style="font-weight: 400;">We’re a team of agency vets and creative leaders who develop simple, intelligent staffing solutions. We work tirelessly to solve the challenges of finding and managing creative talent, so you can focus on getting the job done right. Here’s a closer look at why our partners work with us:</span>'),
(28194, 12104, '_flexible_content_blocks_3_block_content', 'field_663a295ca32b1'),
(28195, 12104, 'flexible_content_blocks_3_slider_section_heading', 'Because we...'),
(28196, 12104, '_flexible_content_blocks_3_slider_section_heading', 'field_664fec9759b9a'),
(28197, 12104, 'flexible_content_blocks_3_slides_0_slide_content', 'have a full network of experienced, highly-skilled creative talent.'),
(28198, 12104, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(28199, 12104, 'flexible_content_blocks_3_slides_1_slide_content', 'reduce the time and effort involved in talent acquisition.'),
(28200, 12104, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
(28201, 12104, 'flexible_content_blocks_3_slides_2_slide_content', 'alleviate operational risks and headaches, allowing you to flex and grow without stress.'),
(28202, 12104, '_flexible_content_blocks_3_slides_2_slide_content', 'field_663a298aa32b4'),
(28203, 12104, 'flexible_content_blocks_3_slides_3_slide_content', 'find the perfect fit based on skills and experience, not job titles.'),
(28204, 12104, '_flexible_content_blocks_3_slides_3_slide_content', 'field_663a298aa32b4'),
(28205, 12104, 'flexible_content_blocks_3_slides_4_slide_content', 'love the creative space, and we know it inside and out.'),
