(28580, 12106, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(28581, 12106, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing ensures you stay on budget, and our Elastic Teams help save more time and money than traditional solutions.'),
(28582, 12106, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(28583, 12106, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
(28584, 12106, '_flexible_content_blocks_2_slides_5_slide_icon', 'field_6644d1f02c90b'),
(28585, 12106, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(28586, 12106, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(28587, 12106, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(28588, 12106, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(28589, 12106, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(28590, 12106, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(28591, 12106, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(28592, 12106, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
(28593, 12106, 'flexible_content_blocks_2_slides_6_slide_eyebrow', ''),
(28594, 12106, '_flexible_content_blocks_2_slides_6_slide_eyebrow', 'field_663a29f727356'),
(28595, 12106, 'flexible_content_blocks_2_slides_6_slide_heading', 'Team Engagement'),
(28596, 12106, '_flexible_content_blocks_2_slides_6_slide_heading', 'field_663a2a0327357'),
(28597, 12106, 'flexible_content_blocks_2_slides_6_slide_content', 'Our “Treat Talent Right” program offers perks and benefits to keep talent performing (and living) their best. And our team is always there to support their needs.'),
(28598, 12106, '_flexible_content_blocks_2_slides_6_slide_content', 'field_663a29d127355'),
(28599, 12106, 'flexible_content_blocks_3_background_color_toggle', 'quinary'),
(28600, 12106, '_flexible_content_blocks_3_background_color_toggle', 'field_6648ff9e0bdfc'),
(28601, 12106, 'flexible_content_blocks_3_background_image', ''),
