(29102, 12108, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(29103, 12108, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing ensures you stay on budget, and our Elastic Teams help save more time and money than traditional solutions.'),
(29104, 12108, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
