(29110, 12108, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(29111, 12108, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(29112, 12108, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(29113, 12108, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
