(29356, 12109, '_flexible_content_blocks_2_slides_2_slide_eyebrow', 'field_663a29f727356'),
(29357, 12109, 'flexible_content_blocks_2_slides_2_slide_heading', 'Scalable Growth'),
(29358, 12109, '_flexible_content_blocks_2_slides_2_slide_heading', 'field_663a2a0327357'),
(29359, 12109, 'flexible_content_blocks_2_slides_2_slide_content', 'Want to invest in your headcount or just need to scale quickly? We’ll help you do it wisely and efficiently.'),
(29360, 12109, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a29d127355'),
(29361, 12109, 'flexible_content_blocks_2_slides', '7'),
