(29375, 12109, 'flexible_content_blocks_2_slides_4_slide_heading', 'Budget'),
(29376, 12109, '_flexible_content_blocks_2_slides_4_slide_heading', 'field_663a2a0327357'),
(29377, 12109, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing ensures you stay on budget, and our Elastic Teams help save more time and money than traditional solutions.'),
(29378, 12109, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(29379, 12109, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
