(29383, 12109, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(29384, 12109, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(29385, 12109, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(29386, 12109, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(29387, 12109, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(29388, 12109, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
