INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(29656, 12111, 'flexible_content_blocks_2_slides_5_slide_eyebrow', ''),
(29657, 12111, '_flexible_content_blocks_2_slides_5_slide_eyebrow', 'field_663a29f727356'),
(29658, 12111, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(29659, 12111, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(29660, 12111, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(29661, 12111, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(29662, 12111, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
(29663, 12111, '_flexible_content_blocks_2_slides_6_slide_icon', 'field_6644d1f02c90b'),
