(29873, 12112, '_flexible_content_blocks_1_hero_eyebrow', 'field_663a2c57af422'),
(29874, 12112, 'flexible_content_blocks_1_hero_heading', 'Become part of our growing community'),
(29875, 12112, '_flexible_content_blocks_1_hero_heading', 'field_663a1e395c04c'),
(29876, 12112, 'flexible_content_blocks_1_hero_content', 'Did you know that roughly half the workforce will be freelance by 2027? So what better reason to join our creative talent pool. When you’re part of Sandy, you’ll have access to a range of roles with some of the best agencies and brands in the game.'),
(29877, 12112, '_flexible_content_blocks_1_hero_content', 'field_663a1e485c04d'),
(29878, 12112, 'flexible_content_blocks_1_hero_cta', 'a:3:{s:5:"title";s:15:"Connect with us";s:3:"url";s:34:"https://jobs.worksandy.com/connect";s:6:"target";s:6:"_blank";}'),
