(29963, 12112, '_flexible_content_blocks_4_testimonials_0_icon', 'field_664a9305b2657'),
(29964, 12112, 'flexible_content_blocks_4_testimonials_0_testimonial', 'I love how easy you guys make everything! Thank you so much :)'),
(29965, 12112, '_flexible_content_blocks_4_testimonials_0_testimonial', 'field_664a88072f803'),
(29966, 12112, 'flexible_content_blocks_4_testimonials_0_attribution', 'Cynthia'),
(29967, 12112, '_flexible_content_blocks_4_testimonials_0_attribution', 'field_664a883f2f804'),
(29968, 12112, 'flexible_content_blocks_4_testimonials_1_icon', '328'),
(29969, 12112, '_flexible_content_blocks_4_testimonials_1_icon', 'field_664a9305b2657'),
(29970, 12112, 'flexible_content_blocks_4_testimonials_1_testimonial', 'Very grateful for all of the kindness, guidance, and professionalism of everyone I’ve interacted with.'),
(29971, 12112, '_flexible_content_blocks_4_testimonials_1_testimonial', 'field_664a88072f803'),
