(29996, 12112, 'flexible_content_blocks_2_slider_section_heading', ''),
(29997, 12112, '_flexible_content_blocks_2_slider_section_heading', 'field_664fec9759b9a'),
(29998, 12112, 'flexible_content_blocks_2_slides_4_slide_content', '<h3><strong>Total Flexibility</strong></h3>\r\n<span style="font-weight: 400;">We give you the freedom to choose the clients that best suit your needs. Plus, most of our clients offer remote work, so you don’t have to move for that dream gig.</span>'),
(29999, 12112, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a298aa32b4'),
(30000, 12112, 'flexible_content_blocks_4_testimonials_2_icon', '328'),
(30001, 12112, '_flexible_content_blocks_4_testimonials_2_icon', 'field_664a9305b2657'),
(30002, 12112, 'flexible_content_blocks_4_testimonials_2_testimonial', 'SANDY is phenomenal! You are nothing like others I have worked for. I always had a positive experience with the entire Sandy team.'),
(30003, 12112, '_flexible_content_blocks_4_testimonials_2_testimonial', 'field_664a88072f803'),
(30004, 12112, 'flexible_content_blocks_4_testimonials_2_attribution', 'James'),
(30005, 12112, '_flexible_content_blocks_4_testimonials_2_attribution', 'field_664a883f2f804'),
(30006, 12112, 'flexible_content_blocks_4_testimonials_3_icon', '328'),
(30007, 12112, '_flexible_content_blocks_4_testimonials_3_icon', 'field_664a9305b2657'),
(30008, 12112, 'flexible_content_blocks_4_testimonials_3_testimonial', 'I am thrilled to have been a part of what Sandy is providing for not only the creative industry, but the freelance space. I haven’t met any person connected to Sandy that wasn’t an absolute gem of a being.'),
(30009, 12112, '_flexible_content_blocks_4_testimonials_3_testimonial', 'field_664a88072f803'),
(30010, 12112, 'flexible_content_blocks_4_testimonials_3_attribution', 'Tiffany'),
(30011, 12112, '_flexible_content_blocks_4_testimonials_3_attribution', 'field_664a883f2f804'),
(30012, 12112, 'flexible_content_blocks_4_testimonials_4_icon', '328'),
(30013, 12112, '_flexible_content_blocks_4_testimonials_4_icon', 'field_664a9305b2657'),
(30014, 12112, 'flexible_content_blocks_4_testimonials_4_testimonial', 'The more I connect with others in the design space the more apparent it becomes that Sandy is truly the best solution for everyone all around.'),
(30015, 12112, '_flexible_content_blocks_4_testimonials_4_testimonial', 'field_664a88072f803'),
(30016, 12112, 'flexible_content_blocks_4_testimonials_4_attribution', 'Nick'),
(30017, 12112, '_flexible_content_blocks_4_testimonials_4_attribution', 'field_664a883f2f804'),
(30018, 12112, 'flexible_content_blocks_4_testimonials_5_icon', '328'),
(30019, 12112, '_flexible_content_blocks_4_testimonials_5_icon', 'field_664a9305b2657'),
(30020, 12112, 'flexible_content_blocks_4_testimonials_5_testimonial', 'Big thanks to you and the rest of the team for crafting such a close-knit remote work environment.'),
(30021, 12112, '_flexible_content_blocks_4_testimonials_5_testimonial', 'field_664a88072f803'),
(30022, 12112, 'flexible_content_blocks_4_testimonials_5_attribution', 'Tyler'),
