INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(30056, 12113, 'flexible_content_blocks_0_column_1_eyebrow', ''),
(30057, 12113, '_flexible_content_blocks_0_column_1_eyebrow', 'field_5c1acaf4ef3c6'),
(30058, 12113, 'flexible_content_blocks_0_column_1_heading', ''),
(30059, 12113, '_flexible_content_blocks_0_column_1_heading', 'field_663a23ca43445'),
(30060, 12113, 'flexible_content_blocks_0_column_1_content', '<h3>We eliminate the pain points of finding and managing creative talent</h3>\r\n\r\nWhen you partner with Sandy, you get access to experts who\'ve spent decades building creative teams for leading brands and agencies. We\'ve been where you are and understand your objectives—which means less worry and more reaching your goals.\r\n\r\nWhy Sandy?\r\n<ul>\r\n 	<li>Top-Tier Talent</li>\r\n 	<li>Reduced Workload</li>\r\n 	<li>Creative Expertise</li>\r\n 	<li>Unrivaled Flexibility</li>\r\n 	<li>Peace of Mind</li>\r\n</ul>\r\n\r\nIf you’re ready, let’s get started!\r\n'),
(30061, 12113, '_flexible_content_blocks_0_column_1_content', 'field_663a23d643446'),
(30062, 12113, 'flexible_content_blocks_0_column_1_cta', ''),
