(30360, 12149, 'flexible_content_blocks_3_slides_0_slide_content', 'have a full network of experienced, highly-skilled creative talent.'),
(30361, 12149, '_flexible_content_blocks_3_slides_0_slide_content', 'field_663a298aa32b4'),
(30362, 12149, 'flexible_content_blocks_3_slides_1_slide_content', 'reduce the time and effort involved in talent acquisition.'),
(30363, 12149, '_flexible_content_blocks_3_slides_1_slide_content', 'field_663a298aa32b4'),
(30364, 12149, 'flexible_content_blocks_3_slides_2_slide_content', 'alleviate operational risks and headaches, allowing you to flex and grow without stress.'),
(30365, 12149, '_flexible_content_blocks_3_slides_2_slide_content', 'field_663a298aa32b4'),
(30366, 12149, 'flexible_content_blocks_3_slides_3_slide_content', 'find the perfect fit based on skills and experience, not job titles.'),
(30367, 12149, '_flexible_content_blocks_3_slides_3_slide_content', 'field_663a298aa32b4'),
