(30517, 12150, 'flexible_content_blocks_2_slides_1_slide_content', 'Need a skills boost? Our network of creatives can fill any need.'),
(30518, 12150, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a29d127355'),
