(30549, 12150, 'flexible_content_blocks_2_slides_5_slide_heading', 'Operations'),
(30550, 12150, '_flexible_content_blocks_2_slides_5_slide_heading', 'field_663a2a0327357'),
(30551, 12150, 'flexible_content_blocks_2_slides_5_slide_content', 'It’s a full-time job managing payroll, contract management, compliance, IT, benefit management, and onboarding. And we can manage it all with ease.'),
(30552, 12150, '_flexible_content_blocks_2_slides_5_slide_content', 'field_663a29d127355'),
(30553, 12150, 'flexible_content_blocks_2_slides_6_slide_icon', '303'),
