INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(30676, 12150, '_flexible_content_blocks_3_slider_section_heading', 'field_664fec9759b9a'),
(30677, 12150, 'flexible_content_blocks_4_bricks_0_brick_details', 'You’ll have access to our vetted, world-class talent–most of which having 8+ years experience in their field. When we say we work with the best, we mean it.'),
(30678, 12150, '_flexible_content_blocks_4_bricks_0_brick_details', 'field_664fecc859b9b'),
(30679, 12150, 'flexible_content_blocks_4_bricks_1_brick_details', 'We handle all the heavy lifting—including recruiting, talent contracts, onboarding, payments and more.'),
(30680, 12150, '_flexible_content_blocks_4_bricks_1_brick_details', 'field_664fecc859b9b'),
(30681, 12150, 'flexible_content_blocks_4_bricks_2_brick_details', 'We excel in building teams for different needs and sizes. We’re seasoned marketers that know what it takes to help achieve your goals and meet your needs.'),
(30682, 12150, '_flexible_content_blocks_4_bricks_2_brick_details', 'field_664fecc859b9b'),
(30683, 12150, 'flexible_content_blocks_4_bricks_3_brick_details', 'We’ve got flexible solutions for all your challenges—from juggling goals and budgets to handling your to-do lists. And we provide next-level support every step of the way.'),
(30684, 12150, '_flexible_content_blocks_4_bricks_3_brick_details', 'field_664fecc859b9b'),
(30685, 12150, 'flexible_content_blocks_4_bricks_4_brick_details', 'We go the extra mile for our talent. We know them well, we collaborate with them, and we offer a range of benefits to fit their needs.'),
(30686, 12150, '_flexible_content_blocks_4_bricks_4_brick_details', 'field_664fecc859b9b'),
(30687, 12150, 'flexible_content_blocks_5_testimonials_2_icon', '328'),
(30688, 12150, '_flexible_content_blocks_5_testimonials_2_icon', 'field_664a9305b2657'),
(30689, 12150, 'flexible_content_blocks_5_testimonials_2_testimonial', '<span style="font-weight: 400;">Our experience has been wonderful, from finding the perfect talent to managing the onboarding process, and our flex team is a great to work with.</span>'),
