(30725, 12150, 'flexible_content_blocks_4_bricks_5_brick_title', 'Reduced Costs'),
(30726, 12150, '_flexible_content_blocks_4_bricks_5_brick_title', 'field_664a8740c32c9'),
(30727, 12150, 'flexible_content_blocks_4_bricks_5_brick_details', 'We work within your budget to hire talent, streamline operations, and ensure maximum support for your team.'),
(30728, 12150, '_flexible_content_blocks_4_bricks_5_brick_details', 'field_664fecc859b9b'),
