(30778, 12151, 'flexible_content_blocks_2_block_eyebrow', ''),
(30779, 12151, '_flexible_content_blocks_2_block_eyebrow', 'field_663a2947a32af'),
(30780, 12151, 'flexible_content_blocks_2_block_heading', 'Why work <br>with Sandy'),
(30781, 12151, '_flexible_content_blocks_2_block_heading', 'field_663a294fa32b0'),
(30782, 12151, 'flexible_content_blocks_2_block_content', ''),
(30783, 12151, '_flexible_content_blocks_2_block_content', 'field_663a295ca32b1'),
(30784, 12151, 'flexible_content_blocks_2_slides_0_slide_content', '<h3><b>Roles Fit For You</b></h3>\r\n<span style="font-weight: 400;">Our Elastic Teams offer a wide range of opportunities in our network. We work with you to find roles that align with your skills and expertise.</span>'),
(30785, 12151, '_flexible_content_blocks_2_slides_0_slide_content', 'field_663a298aa32b4'),
(30786, 12151, 'flexible_content_blocks_2_slides_1_slide_content', '<h3><strong>Bye, Bye Paperwork</strong></h3>\r\n<span style="font-weight: 400;">We handle your negotiation, contracts, invoicing, and payments, so you can focus on getting to work.</span>'),
(30787, 12151, '_flexible_content_blocks_2_slides_1_slide_content', 'field_663a298aa32b4'),
(30788, 12151, 'flexible_content_blocks_2_slides_2_slide_content', '<h3><b>Better Compensation and Benefits</b></h3>\r\n<span style="font-weight: 400;">It’s tough to get the pay and perks you want. Our team works tirelessly to get the most competitive rate in your field, plus a range of great benefits.</span>'),
(30789, 12151, '_flexible_content_blocks_2_slides_2_slide_content', 'field_663a298aa32b4'),
(30790, 12151, 'flexible_content_blocks_2_slides_3_slide_content', '<h3><strong>Serious Support</strong></h3>\r\n<span style="font-weight: 400;">We’re always in touch with you </span><i><span style="font-weight: 400;">and</span></i><span style="font-weight: 400;"> the client, ensuring you have the support you need to perform and succeed. We want to ensure it works great for all parties involved.</span>'),
(30791, 12151, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a298aa32b4'),
(30792, 12151, 'flexible_content_blocks_2_slides', '5'),
(30793, 12151, '_flexible_content_blocks_2_slides', 'field_663a296da32b2'),
(30794, 12151, 'flexible_content_blocks_3_background_image', '11731'),
