(30798, 12151, 'flexible_content_blocks_3_block_eyebrow', ''),
(30799, 12151, '_flexible_content_blocks_3_block_eyebrow', 'field_663a29d127350'),
(30800, 12151, 'flexible_content_blocks_3_block_heading', 'We Keep It Simple and Easy'),
(30801, 12151, '_flexible_content_blocks_3_block_heading', 'field_663a29d127351'),
(30802, 12151, 'flexible_content_blocks_3_block_content', 'We want to make your experience as painless and straightforward as possible. Here’s a closer look at how it works:'),
(30803, 12151, '_flexible_content_blocks_3_block_content', 'field_663a29d127352'),
(30804, 12151, 'flexible_content_blocks_3_slides_0_slide_icon', '366'),
