(31088, 12152, 'flexible_content_blocks_4_testimonials_3_icon', '328'),
(31089, 12152, '_flexible_content_blocks_4_testimonials_3_icon', 'field_664a9305b2657'),
(31090, 12152, 'flexible_content_blocks_4_testimonials_3_testimonial', 'I am thrilled to have been a part of what Sandy is providing for not only the creative industry, but the freelance space. I haven’t met any person connected to Sandy that wasn’t an absolute gem of a being.'),
(31091, 12152, '_flexible_content_blocks_4_testimonials_3_testimonial', 'field_664a88072f803'),
(31092, 12152, 'flexible_content_blocks_4_testimonials_3_attribution', 'Tiffany'),
