(31192, 12153, 'flexible_content_blocks_2_slides_3_slide_heading', 'Turnover'),
(31193, 12153, '_flexible_content_blocks_2_slides_3_slide_heading', 'field_663a2a0327357'),
(31194, 12153, 'flexible_content_blocks_2_slides_3_slide_content', 'Our process minimizes disruption–whether you need a quick replacement or have an unexpected resignation.'),
(31195, 12153, '_flexible_content_blocks_2_slides_3_slide_content', 'field_663a29d127355'),
(31196, 12153, 'flexible_content_blocks_2_slides_4_slide_icon', '301'),
