(31202, 12153, 'flexible_content_blocks_2_slides_4_slide_content', 'Our predictable pricing ensures you stay on budget, and our Elastic Teams help save more time and money than traditional solutions.'),
(31203, 12153, '_flexible_content_blocks_2_slides_4_slide_content', 'field_663a29d127355'),
(31204, 12153, 'flexible_content_blocks_2_slides_5_slide_icon', '302'),
