(31778, 8041, 'rank_math_description', 'Sandy is hiring creative freelancers! We are a remote first advertising agency powered by top freelance talent. Freelance creatives apply here:'),
(31779, 8041, 'rank_math_focus_keyword', 'hiring creative freelancers'),
(31780, 8041, 'rank_math_news_sitemap_robots', 'index'),
(31781, 8041, 'rank_math_robots', 'a:1:{i:0;s:5:"index";}'),
(31782, 9142, 'rank_math_title', 'Hiring creative talent %sep% %sitename% Apply today.'),
(31783, 9142, 'rank_math_description', 'Sandy is hiring for FT and freelance positions - join our global advertising talent network to work with brands you\'ve heard of.'),
(31784, 9142, 'rank_math_focus_keyword', 'New Roles!'),
