(31840, 11405, 'rank_math_title', '%title% %page% %sep% %sitename% Sandy Hot Take: California and the 32-hour Work Week'),
(31841, 11405, 'rank_math_description', 'California is considering shorting the workweek from 40 to 32 hours. What does an expert at freelance work think about the change? We chime in!'),
(31842, 11405, 'rank_math_news_sitemap_robots', 'index'),
(31843, 11405, 'rank_math_robots', 'a:1:{i:0;s:5:"index";}'),
(31844, 11433, 'rank_math_title', 'The Power of Pay Transparency'),
(31845, 11433, 'rank_math_description', 'Sandy Chief Brand Officer Rae Hames weighs in on this hot topic. Does a culture of salary transparency make for happy employees and a more efficient workplace?'),
(31846, 11433, 'rank_math_news_sitemap_robots', 'index'),
(31847, 11433, 'rank_math_robots', 'a:1:{i:0;s:5:"index";}'),
(31848, 11438, 'rank_math_title', 'Sandy Hot Take: Do You Need a “Wife” to be Successful?'),
(31849, 11438, 'rank_math_description', 'Can we achieve greatness at work when we\'re pulled in five different directions? Was it easier when executives had a "wife" at home to help? Let\'s discuss.'),
(31850, 11438, 'rank_math_news_sitemap_robots', 'index'),
