(32210, 12154, '__validate_email', '_validate_email'),
(32211, 2, 'rank_math_description', 'Creative Staffing. Simply done better. At Sandy, we connect AI-ready creative talent with forward-thinking organizations. '),
(32212, 2, 'rank_math_focus_keyword', 'Creative Staffing,AI-ready'),
(32213, 2, 'cmplz_hide_cookiebanner', ''),
(32214, 12139, '_edit_lock', '1740596895:5'),
(32215, 59, 'rank_math_description', 'We’re specialists who excel at creative team building and talent solutions, fully aware of how important it is to find the right talent.'),
(32216, 59, 'rank_math_focus_keyword', 'Creative Team Building,Talent Solutions,Find the Right Talent'),
(32217, 61, 'rank_math_description', 'We make creative staffing simple. From recruitment to Elastic Teams and managed services, our solutions ensure you have the right talent at the right time—so you can spend less energy on resourcing and more time achieving your goals.'),
(32218, 61, 'rank_math_focus_keyword', 'creative staffing,Elastic Teams'),
(32219, 63, 'rank_math_description', 'Join Sandy and gain access to roles with some of the best agencies and brands in the game.'),
(32220, 63, 'rank_math_focus_keyword', 'Join Sandy,Job Opportunities'),
(32221, 213, 'rank_math_description', 'Scale your creative and marketing teams with ease. We eliminate the pain points of finding and managing AI-ready creative talent. Flexible, trusted, built around you.'),
(32222, 213, 'rank_math_focus_keyword', 'find talent,creative and marketing teams,AI-Ready'),
(32223, 213, 'cmplz_hide_cookiebanner', ''),
(32224, 57, 'rank_math_contentai_score', 'a:5:{s:8:"keywords";s:5:"74.51";s:9:"wordCount";s:1:"0";s:9:"linkCount";s:1:"0";s:12:"headingCount";s:1:"0";s:10:"mediaCount";s:1:"0";}'),
(32225, 57, 'rank_math_description', 'Insights for marketing and creative leaders: Explore articles on creative resource planning, flexible staffing strategies, and optimizing in-house and freelance teams to drive business growth.'),
(32226, 57, 'rank_math_focus_keyword', 'creative resource planning,staffing strategies,marketing insights,creative insights'),
