(33685, 12280, 'flexible_content_blocks_4_bricks_3_brick_details', 'Our flexible solutions help you balance goals, budgets, and day-to-day challenges with ease.'),
(33686, 12280, '_flexible_content_blocks_4_bricks_3_brick_details', 'field_664fecc859b9b'),
(33687, 12280, 'flexible_content_blocks_4_bricks_4_brick_details', 'We go the extra mile: we know our talent, collaborate closely, and offer benefits that fit their needs.'),
(33688, 12280, '_flexible_content_blocks_4_bricks_4_brick_details', 'field_664fecc859b9b'),
