INSERT INTO `ULhz1h_postmeta` ( `meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(34379, 12303, '_wp_attachment_image_alt', 'Photo collage from Google’s “Culture Meets AI” sessions during LA Tech Week, featuring the Sandy team with event speakers and attendees. Images show panels on AI and creativity, industry leaders discussing the state of the LA AI ecosystem, and candid moments of collaboration and connection.'),
(34380, 12298, '_wp_attachment_image_alt', 'Graphic quote reading “AI can generate a scene, but only humans can give it a soul,” displayed in bold navy blue text with large light-grey quotation marks in the background.'),
(34381, 12300, '_wp_attachment_image_alt', 'Quote graphic featuring the text: “We can now test creative across synthetic audiences of thousands in days rather than six-month focus groups.” — Ryan Hamill, Creative Director at ServiceNow. The quote appears in bold navy text with large beige quotation marks in the background.'),
(34382, 12301, '_wp_attachment_image_alt', 'Quote graphic reading “AI is a club that lets too many people in with fake IDs.” — Adriana Gosford, CMO of Artera. The text appears in bold navy lettering over a white background with large, light-grey quotation marks behind it.'),
(34383, 12302, '_wp_attachment_image_alt', 'Quote graphic reading “The differentiator soon won’t be the tools, it’ll be your people.” — Ryan Hamill, Creative Director at ServiceNow. The text is in bold navy blue on a white background with large soft pink quotation marks behind it.'),
(34384, 12299, '_wp_attachment_image_alt', 'Quote graphic reading “AI isn’t replacing creators; it’s giving them more time to tell better stories.” — Julia Lan, Former Head of Growth at TikTok. The text appears in bold navy blue on a white background with large light-teal quotation marks behind it.'),
(34385, 12295, 'rank_math_og_content_image', 'a:2:{s:5:"check";s:32:"77d4f740c24539fb144de055f50e0f9e";s:6:"images";a:1:{i:0;i:12303;}}'),
(34386, 12295, 'rank_math_seo_score', '72'),
(34387, 12295, 'rank_math_contentai_score', 'a:5:{s:8:"keywords";s:5:"74.51";s:9:"wordCount";s:1:"0";s:9:"linkCount";s:1:"0";s:12:"headingCount";s:1:"0";s:10:"mediaCount";s:1:"0";}'),
(34388, 12295, 'rank_math_description', 'Discover the top 5 creative and marketing themes from LA Tech Week, where leaders from Google, McKinsey, and Amazon explored how AI is reshaping creativity. Learn why the future of AI and Marketing belongs to human storytellers who know how to collaborate with intelligent tools.'),
(34389, 12295, 'rank_math_focus_keyword', 'ai and marketing,AI creativity,creative storytelling,Human + AI,AI-ready teams'),
